// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= address(this).balance || amount > 0);
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(actor != address(0));

        vm.deal(actor, amount);
        (, uint256 beforeBal) = c.Acc(actor);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.Put.selector, uint256(0)));
        assertTrue(ok);

        (, uint256 afterBal) = c.Acc(actor);
        // Universal rule: after any successful Put of `amount`, the caller's recorded
        // balance must include the deposit (increase by exactly amount).
        assertTrue(afterBal == beforeBal + amount && afterBal >= amount);
    }
}

