pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.warp(1000);
        amount = bound(amount, 1 ether, 1000 ether);
        // any unlock time in the past relative to the current timestamp is admissible
        unlockTime = bound(unlockTime, 0, block.timestamp - 1);

        address actor = address(0xABCD);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // right after the deposit, the deposit is still locked: Collect must not pay out
        vm.prank(actor);
        c.Collect(amount);

        assertTrue(c.Acc(actor).balance() == amount);
    }
}

