pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 pastT, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 10 ether);
        pastT = bound(pastT, 0, block.timestamp > 0 ? block.timestamp - 1 : 0);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(pastT);

        // move time forward strictly past the Put transaction
        vm.warp(block.timestamp + 1);

        // a later Put with unlockTime 0 must re-lock: stored unlock time >= now
        vm.prank(actor);
        c.Put{value: 0}(0);

        assertTrue(c.Acc(actor).unlockTime >= block.timestamp);
    }
}

