contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount >= 1 ether);
        require(address(this).balance >= amount);
        c.Put{value: amount}(0);
        (, uint bal0) = c.Acc(address(this));
        require(bal0 == amount);
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        (, uint bal1) = c.Acc(address(this));
        assert(reverted || bal1 + amount == bal0);
    }
    receive() external payable {}
}

